package com.portfolio.assetory.inquiry.domain;
import java.time.LocalDateTime;import com.portfolio.assetory.member.domain.User;import com.portfolio.assetory.product.domain.Product;import jakarta.persistence.*;
@Entity @Table(name="inquiry_rooms",uniqueConstraints=@UniqueConstraint(name="uk_inquiry_buyer_product_seller",columnNames={"buyer_id","product_id","seller_id"})) public class InquiryRoom{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="buyer_id",nullable=false)private User buyer;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="seller_id",nullable=false)private User seller;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="product_id",nullable=false)private Product product;@Enumerated(EnumType.STRING)@Column(nullable=false)private InquiryRoomStatus status;@Column(nullable=false,updatable=false)private LocalDateTime createdAt;private LocalDateTime closedAt;protected InquiryRoom(){}public static InquiryRoom create(User b,Product p){InquiryRoom r=new InquiryRoom();r.buyer=b;r.seller=p.getSeller();r.product=p;r.status=InquiryRoomStatus.OPEN;return r;}@PrePersist void created(){createdAt=LocalDateTime.now();}public void close(){status=InquiryRoomStatus.CLOSED;closedAt=LocalDateTime.now();}public Long getId(){return id;}public User getBuyer(){return buyer;}public User getSeller(){return seller;}public Product getProduct(){return product;}public InquiryRoomStatus getStatus(){return status;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getClosedAt(){return closedAt;}}
